<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}">
    <title>Driver Portal | {{ config('app.name') }}</title>
    <style>
        :root { --ink:#15251f; --brand:#1d7558; --brand-dark:#155a43; --paper:#fff; --muted:#65766d; --line:#d8e4dc; --bg:#f4faf6; --danger:#a92f2f; --warning:#a66c00; }*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,sans-serif}button,input{font:inherit}.shell{max-width:920px;margin:auto;padding:22px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}.brand{font-weight:900;color:var(--brand);letter-spacing:.03em}.brand span{display:inline-grid;width:28px;height:28px;place-items:center;color:#fff;background:var(--brand);border-radius:8px;margin-right:7px}.profile{display:flex;align-items:center;gap:12px}.profile small{display:block;color:var(--muted)}.logout{border:1px solid var(--line);color:var(--ink);background:#fff;border-radius:9px;padding:9px 12px;cursor:pointer}.grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(250px,.8fr);gap:18px}.card{background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:21px;box-shadow:0 5px 18px rgba(30,70,48,.04)}.card h1,.card h2{margin:0}.card h1{font-size:25px}.sub{color:var(--muted);margin:8px 0 0}.availability{margin-top:22px;display:flex;align-items:center;justify-content:space-between;gap:14px;background:#f1f7f3;border-radius:13px;padding:14px}.status{display:flex;gap:9px;align-items:center;font-weight:800}.dot{width:10px;height:10px;border-radius:50%;background:#98aaa0}.dot.online{background:#28a867;box-shadow:0 0 0 5px #d9f3e4}.switch{position:relative;width:54px;height:31px}.switch input{opacity:0;width:0;height:0}.slider{position:absolute;inset:0;border-radius:20px;background:#cbd7cf;cursor:pointer}.slider:before{content:"";position:absolute;width:23px;height:23px;left:4px;bottom:4px;background:#fff;border-radius:50%;transition:.2s}.switch input:checked+.slider{background:var(--brand)}.switch input:checked+.slider:before{transform:translateX(23px)}.facts{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px}.fact{border:1px solid var(--line);border-radius:11px;padding:12px}.fact b{display:block;font-size:13px;color:var(--muted);margin-bottom:5px}.empty{margin-top:16px;padding:17px;border:1px dashed #b7cabd;border-radius:12px;color:var(--muted)}.request{display:none;position:fixed;inset:0;background:rgba(11,29,20,.46);z-index:10;align-items:center;justify-content:center;padding:20px}.request.show{display:flex}.modal{width:min(100%,480px);background:#fff;border-radius:20px;padding:24px;box-shadow:0 24px 70px rgba(0,0,0,.24)}.eyebrow{color:var(--brand);font-weight:800;font-size:13px;text-transform:uppercase;letter-spacing:.08em}.timer{font-size:31px;font-weight:900;color:var(--warning);margin:12px 0}.locations{margin:14px 0;padding:12px;background:#f7faf8;border-radius:12px;line-height:1.55}.actions,.trip-actions{display:flex;gap:10px;margin-top:17px}.primary,.secondary{flex:1;border:0;border-radius:10px;padding:12px;font-weight:800;cursor:pointer}.primary{color:#fff;background:var(--brand)}.secondary{color:var(--ink);background:#ecf2ee}.trip-actions input{min-width:160px;flex:1;border:1px solid var(--line);border-radius:10px;padding:11px}.message{margin-top:14px;min-height:20px;font-size:14px;color:var(--muted)}.message.error{color:var(--danger)}.message.success{color:var(--brand-dark)}@media(max-width:700px){.shell{padding:16px}.grid{grid-template-columns:1fr}.topbar{align-items:flex-start}.profile{flex-wrap:wrap;justify-content:flex-end}.facts{grid-template-columns:1fr}.actions,.trip-actions{flex-direction:column}.trip-actions input{width:100%}}
    </style>
</head>
<body>
    <main class="shell">
        <header class="topbar"><div class="brand"><span>D</span>DROPA2Z DRIVER</div><div class="profile"><div><strong>{{ $driver->name }}</strong><small>{{ $driver->email }}</small></div><form method="POST" action="{{ route('driver.portal.logout') }}">@csrf<button class="logout" type="submit">Sign out</button></form></div></header>
        <div class="grid"><section class="card"><h1>Driver dashboard</h1><p class="sub">Use location permission before going online. Ride requests appear here automatically.</p><div class="availability"><div class="status"><span id="status-dot" class="dot {{ $driver->is_online ? 'online' : '' }}"></span><span id="availability-label">{{ $driver->is_online ? 'You are online' : 'You are offline' }}</span></div><label class="switch" aria-label="Driver availability"><input id="availability" type="checkbox" {{ $driver->is_online ? 'checked' : '' }}><span class="slider"></span></label></div><p id="location-message" class="message">Location updates are {{ $driver->is_online ? 'active' : 'paused' }}.</p>
            @if ($activeRide)<div class="card" style="margin-top:18px;background:#fbfefc"><span class="eyebrow">Current trip</span><h2 style="margin-top:7px">Ride #{{ $activeRide->ride_number }}</h2><p class="sub">{{ $activeRide->locations[0] ?? 'Pickup' }} → {{ $activeRide->locations[count($activeRide->locations ?? []) - 1] ?? 'Drop' }}</p><div class="facts"><div class="fact"><b>Rider</b>{{ data_get($activeRide->rider, 'name', 'Rider') }}</div><div class="fact"><b>Status</b>{{ ucfirst(data_get($activeRide->ride_status, 'slug', 'accepted')) }}</div></div>@if (data_get($activeRide->ride_status, 'slug') === 'accepted')<div class="trip-actions"><input id="ride-otp" inputmode="numeric" maxlength="12" placeholder="Ask rider for trip OTP"><button class="primary" type="button" onclick="startRide({{ $activeRide->id }})">Start trip</button></div>@else<div class="trip-actions"><button class="primary" type="button" onclick="completeRide({{ $activeRide->id }})">Complete trip</button></div>@endif</div>@else<div class="empty">No active trip. Go online and keep this page open to receive ride requests.</div>@endif
        </section><aside class="card"><h2>Vehicle details</h2><div class="facts"><div class="fact"><b>Vehicle</b>{{ $driver->vehicle_info?->vehicle?->name ?? 'Not assigned' }}</div><div class="fact"><b>Plate number</b>{{ $driver->vehicle_info?->plate_number ?? 'Not added' }}</div><div class="fact"><b>Service</b>{{ $driver->service?->name ?? 'Not assigned' }}</div><div class="fact"><b>Account</b>{{ $driver->is_verified ? 'Verified' : 'Pending' }}</div></div></aside></div>
    </main>
    <div id="ride-request" class="request" role="dialog" aria-modal="true" aria-labelledby="ride-request-title"><div class="modal"><span class="eyebrow">New ride request</span><h2 id="ride-request-title" style="margin-top:7px">A rider needs a trip</h2><div id="request-timer" class="timer">00:30</div><div id="request-details" class="locations"></div><div class="actions"><button class="secondary" type="button" onclick="rejectRideRequest()">Reject</button><button class="primary" type="button" onclick="acceptRideRequest()">Accept ride</button></div></div></div>
    <script>
        const routes={availability:@json(route('driver.portal.availability')),location:@json(route('driver.portal.location')),current:@json(route('driver.portal.ride-request.current')),accept:@json(route('driver.portal.ride-request.accept')),reject:@json(route('driver.portal.ride-request.reject')),start:@json(route('driver.portal.ride.start')),complete:@json(route('driver.portal.ride.complete'))},csrf=document.querySelector('meta[name="csrf-token"]').content;let currentRequest=null,locationWatch=null,lastLocationSentAt=0,countdownTimer=null;
        async function requestJson(url,method='POST',data=null){const response=await fetch(url,{method,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:data?JSON.stringify(data):null}),payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.message||payload.error||'Please try again.');return payload}function message(text,error=false){const el=document.getElementById('location-message');el.textContent=text;el.className=`message ${error?'error':'success'}`}function setAvailabilityUi(online){document.getElementById('availability').checked=online;document.getElementById('availability-label').textContent=online?'You are online':'You are offline';document.getElementById('status-dot').classList.toggle('online',online)}function coordinates(position){return{lat:position.coords.latitude,lng:position.coords.longitude}}function getPosition(){return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:15000}))}
        document.getElementById('availability').addEventListener('change',async event=>{const online=event.target.checked;try{let location=null;if(online){if(!navigator.geolocation)throw new Error('This browser does not support location.');location=coordinates(await getPosition())}const result=await requestJson(routes.availability,'POST',{is_online:online,location});setAvailabilityUi(Boolean(result.is_online));if(result.is_online){startLocationWatch();message('You are online. Looking for rides nearby.');pollRideRequest()}else{stopLocationWatch();closeRequest();message('You are offline. Location sharing is paused.')}}catch(error){setAvailabilityUi(!online);message(error.message,true)}});
        function startLocationWatch(){if(!navigator.geolocation||locationWatch!==null)return;locationWatch=navigator.geolocation.watchPosition(async position=>{if(Date.now()-lastLocationSentAt<15000)return;lastLocationSentAt=Date.now();try{await requestJson(routes.location,'POST',{location:coordinates(position)})}catch(error){message(error.message,true)}},()=>message('Location permission is needed to stay online.',true),{enableHighAccuracy:true,maximumAge:10000})}function stopLocationWatch(){if(locationWatch!==null)navigator.geolocation.clearWatch(locationWatch);locationWatch=null}async function pollRideRequest(){if(!document.getElementById('availability').checked||currentRequest)return;try{const payload=await requestJson(routes.current,'GET');if(payload&&payload.id)showRequest(payload)}catch(error){console.warn('Ride request check failed.',error)}}function showRequest(request){currentRequest=request;const from=request.locations?.[0]||'Pickup',to=request.locations?.[request.locations.length-1]||'Drop';document.getElementById('request-details').textContent=`${from} → ${to} · ${request.distance||0} ${request.distance_unit||'km'} · ${request.currency_symbol||'₹'}${request.total||request.ride_fare||0}`;document.getElementById('ride-request').classList.add('show');updateTimer();countdownTimer=window.setInterval(updateTimer,1000)}function updateTimer(){if(!currentRequest)return;const seconds=Math.max(0,Math.ceil((new Date(currentRequest.driver_acceptance_expires_at).getTime()-Date.now())/1000));document.getElementById('request-timer').textContent=`00:${String(seconds).padStart(2,'0')}`;if(seconds===0)closeRequest()}function closeRequest(){if(countdownTimer)clearInterval(countdownTimer);countdownTimer=null;currentRequest=null;document.getElementById('ride-request').classList.remove('show')}
        async function acceptRideRequest(){if(!currentRequest)return;try{await requestJson(routes.accept,'POST',{ride_request_id:currentRequest.id});window.location.reload()}catch(error){closeRequest();message(error.message,true)}}async function rejectRideRequest(){if(!currentRequest)return;try{await requestJson(routes.reject,'POST',{ride_request_id:currentRequest.id});closeRequest();message('Ride request rejected.')}catch(error){closeRequest();message(error.message,true)}}async function startRide(rideId){const otp=document.getElementById('ride-otp').value.trim();if(!otp)return message('Ask the rider for the trip OTP first.',true);try{const location=coordinates(await getPosition());await requestJson(routes.start,'POST',{ride_id:rideId,otp,start_ride_locations:['Current driver location'],start_ride_coordinates:[location]});window.location.reload()}catch(error){message(error.message,true)}}async function completeRide(rideId){if(!window.confirm('Complete this trip?'))return;try{await requestJson(routes.complete,'POST',{ride_id:rideId});window.location.reload()}catch(error){message(error.message,true)}}if(document.getElementById('availability').checked){startLocationWatch();window.setInterval(pollRideRequest,5000);pollRideRequest()}
    </script>
</body>
</html>
